#[test]
fn test_state_read_keys_in_loop_steps_match_jq_7473() -> Result<()> {
    for (program, stdout, stderr, code) in CASES {
        let got = run_jq_full(&["-nc", program], None)?;
        assert_eq!(
            (got.0.as_str(), got.1.as_str(), got.2),
            (*stdout, *stderr, *code),
            "{program}"
        );
    }
    Ok(())
}
